static const struct {
    unsigned short in;
    unsigned out;
} to_single[] = {
    {0x0001, 0x33800000},
    {0x03ff, 0x387fc000},
    {0x0400, 0x38800000},
    {0x3c00, 0x3f800000},
    {0x7bff, 0x477fe000},
    {0xfbff, 0xc77fe000},
    {0x7c00, 0x7f800000},
    {0x7c01, 0x7fc02000},
    {0xfe01, 0xffc02000},
};

static unsigned convert(float f, int imm) {
    switch (imm) {
    case 0: return _cvtss_sh(f, 0);
    case 1: return _cvtss_sh(f, 1);
    case 2: return _cvtss_sh(f, 2);
    case 3: return _cvtss_sh(f, 3);
    default: return _cvtss_sh(f, 4);
    }
}

int main(void) {
    unsigned saved = _mm_getcsr();
    for (unsigned k = 0; k < sizeof to_half / sizeof *to_half; k++) {
        float f;
        memcpy(&f, &to_half[k].in, 4);
        _mm_setcsr(to_half[k].csr);
        unsigned h = convert(f, to_half[k].imm), flags = _mm_getcsr() & 0x3f;
        _mm_setcsr(saved);
        if (h != to_half[k].half || flags != to_half[k].flags)
            return 1;
    }
    for (unsigned k = 0; k < sizeof to_single / sizeof *to_single; k++) {
        float f = _cvtsh_ss(to_single[k].in);
        unsigned u;
        memcpy(&u, &f, 4);
        if (u != to_single[k].out)
            return 2;
    }
    __m256 v = _mm256_set_ps(8.0f, 7.0f, 6.0f, 5.0f, 4.0f, 3.0f, 2.0f, 1.0f);
    __m128i h8 = _mm256_cvtps_ph(v, 0), h4 = _mm_cvtps_ph(_mm256_castps256_ps128(v), 0);
    unsigned short got8[8], got4[8];
    memcpy(got8, &h8, sizeof got8);
    memcpy(got4, &h4, sizeof got4);
    static const unsigned short want[8] = {0x3c00, 0x4000, 0x4200, 0x4400,
                                           0x4500, 0x4600, 0x4700, 0x4800};
    for (int i = 0; i < 8; i++)
        if (got8[i] != want[i] || got4[i] != (i < 4 ? want[i] : 0))
            return 3;
    __m256 back = _mm256_cvtph_ps(h8);
    __m128 back4 = _mm_cvtph_ps(h8);
    for (int i = 0; i < 8; i++)
        if (back[i] != (float)(i + 1) || (i < 4 && back4[i] != (float)(i + 1)))
            return 4;
    return 0;
}
